<script setup lang="ts">
import { ref, reactive, onMounted } from 'vue'
import { useRouter,useRoute } from 'vue-router'
import { useUserStore } from '@/store/user'
import { useAppStore } from '@/store/index'
import { useTimeUtils } from '@/utils/time'
import useMd5 from '@/utils/useMd5'
import { showToast, showConfirmDialog,showLoadingToast } from 'vant'
import nzhcn from "nzh/cn";

// 路由和状态管理
const router = useRouter()
const route = useRoute()
const userStore = useUserStore()
const appStore = useAppStore()
const userTime = useTimeUtils()
const md5 = useMd5();
const num = ref(3)
const tits = ref('子账号管理')
const logInfo = ref('')


// ==================== 数据定义 ====================
const zstus = {
    1: '启用',
    2: '禁用',
    3: '冻结',
}

const zdSelect = ref(false)
const moreShow = ref(false)
const uitem = ref('')
const subAccountList = ref([])
const loglist = ref([])
const logall = ref(false)
const logshow = ref(false)
const showStart = ref(false)
const showEnd = ref(false)
const currentDate = ref(new Date())

const listQuery = reactive({
    object: {
        status: 1,
        starte: '',
        end: ''
    },
    pageNum: 0,
    pageSize: 10,
})

const logparm = reactive({
    object: {
        start: '',
        end: '',
        operId: '',
        assignedId: '',
        ip: '',
        modType: '',
        controlType: '',
        funType: ''
    },
    pageNum: 0,
    pageSize: 8,
    total: 0,
})

// ==================== 辅助函数 ====================
const formatTime = (date) => {
    var seperator1 = "-"
    var year = date.getFullYear()
    var month = date.getMonth() + 1
    var hour = date.getHours()
    var minutes = date.getMinutes()
    var seconds = date.getSeconds()
    var strDate = date.getDate()
    
    if (month >= 1 && month <= 9) {
        month = "0" + month
    }
    if (strDate >= 0 && strDate <= 9) {
        strDate = "0" + strDate
    }
    var currentdate = year + seperator1 + month + seperator1 + strDate + "  " + hour + ":" + minutes + ":00"
    
    return currentdate
}

// ==================== 主要方法 ====================
const pktab = () => {
    zdSelect.value = !zdSelect.value
}

const moTab = (item) => {
    moreShow.value = !moreShow.value
    uitem.value = item
}

const sztab = (num) => {
    listQuery.object.status = num
    listQuery.pageNum = 0
    zdSelect.value = false
    getSubAccountList()
}

const confirmTime = (val, field) => {
    const time = formatTime(val)
    if (time) {
        if (field === 'start') {
            listQuery.object.starte = time
        } else {
            listQuery.object.end = time
        }
    }
    cancelTime()
}

const cancelTime = () => {
    showStart.value = false
    showEnd.value = false
}

const getclist = () => {
    logparm.object.start = ''
    logparm.object.end = ''
}

const logChange = (val) => {
    console.log(`每页 ${val} 条`)
}

const logcurChange = (val) => {
    logparm.pageNum = val
    getlogs()
}

const logtab = (obj, num) => {
    logparm.pageNum = 0
    loglist.value = []
    clearList()
    if (num == 1) {
        logparm.object.assignedId = obj.id
        logall.value = true
    } else {
        logparm.object.assignedId = obj.id
        logparm.object.modType = 3
        logparm.object.funType = 7
        logshow.value = true
    }
    getlogs()
}

const clearList = () => {
    logparm.object.start = ''
    logparm.object.end = ''
    logparm.object.operId = ''
    logparm.object.assignedId = ''
    logparm.object.ip = ''
    logparm.object.modType = ''
    logparm.object.controlType = ''
    logparm.object.funType = ''
    logparm.pageNum = 0
    logparm.pageSize = 8
}

const closelog = () => {
    logall.value = false
    logshow.value = false
}

const getlogs = async () => {
    try {
        let t1 = ""
        let t2 = ""
        if (logparm.object.start) {
            t1 = logparm.object.start + ' 00:00:00'
        }
        if (logparm.object.end) {
            t2 = logparm.object.end + ' 23:59:59'
        }
        let bbb = {
            object: {
                start: t1,
                end: t2,
                operId: logparm.object.operId,
                assignedId: logparm.object.assignedId,
                ip: logparm.object.ip,
                modType: logparm.object.modType,
                controlType: logparm.object.controlType,
                funType: logparm.object.funType
            },
            pageNum: logparm.pageNum,
            pageSize: logparm.pageSize,
        }
        
        const res = await userStore.getPageLogs(bbb)
        
        if (res.data && res.data.list) {
            res.data.list.map(item => {
                if (item.origin) {
                    if (item.origin.indexOf(',') >= 0) {
                        item.orlist = item.origin.split(",")
                    } else {
                        item.orlist = []
                        item.orlist.push(item.origin)
                    }
                }
                if (item.changed) {
                    if (item.changed.indexOf(',') >= 0) {
                        item.chlist = item.changed.split(",")
                    } else {
                        item.chlist = []
                        item.chlist.push(item.changed)
                    }
                }
            })
            loglist.value = res.data.list
            logparm.pageSize = res.data.pageSize
            logparm.total = res.data.total
        }
    } catch (error) {
        console.error('getlogs error:', error)
    }
}

const backHandle = () => {
    router.push('/UserManage')
}

const getSubAccountList = async () => {
    try {
        const res = await userStore.getChildPage(listQuery)
        if (res.data) {
            subAccountList.value = res.data.list
            listQuery.pageSize = res.data.pageSize
        }
    } catch (error) {
        console.log('getSubAccountList error:', error)
    }
}

const resetError = async (item) => {
    try {
        const res = await userStore.getLoginFalseCount(item.id)
        showToast({
            message: '操作成功',
            className: 'custom-toast',
            duration: 1000  // 自定义显示时间
        });
        await getSubAccountList()
    } catch (error) {
        console.error('resetError error:', error)
    }
}

const handleCurrentChange = (val) => {
    listQuery.pageNum = val
    getSubAccountList()
}

const enableStatus = async (item) => {
    try {
        let str = {
            account: item.account,
            id: item.id,
            status: item.status,
        }
        const res = await userStore.getChildStatus(str)
        showToast({
            message: '操作成功',
            className: 'custom-toast',
            duration: 1000  // 自定义显示时间
        });
        await getSubAccountList()
    } catch (error) {
        console.error('enableStatus error:', error)
    }
}

// ==================== 生命周期 ====================
onMounted(() => {
    let ust = JSON.parse(localStorage.getItem('userInfo'))
    logInfo.value = ust
    listQuery.object.layer = 100
    listQuery.object.role = 4
    getSubAccountList()
})
</script>

